def gen(rng):
    DIRS = ((0, -1), (1, 0), (1, -1), (1, 1))

    def run_len(g, r, c, i, j, di, dj, ch):
        n = 0
        i += di
        j += dj
        while n < 3 and 0 <= i < r and 0 <= j < c and g[i][j] == ch:
            n += 1
            i += di
            j += dj
        return n

    def makes_four(g, r, c, i, j, ch):
        for di, dj in DIRS:
            if run_len(g, r, c, i, j, di, dj, ch) >= 3:
                return True
        return False

    def has4(g, r, c, ch):
        t = ch * 4
        for row in g:
            if t in ''.join(row):
                return True
        for col in zip(*g):
            if t in ''.join(col):
                return True
        a = [[] for _ in range(r + c)]
        b = [[] for _ in range(r + c)]
        for i in range(r):
            row = g[i]
            for j in range(c):
                a[i - j + c - 1].append(row[j])
                b[i + j].append(row[j])
        for x in a + b:
            if t in ''.join(x):
                return True
        return False

    def fill(r, c, h, fixed):
        g = [['.'] * c for _ in range(r)]
        for i in range(r - 1, -1, -1):
            lvl = r - 1 - i
            row = g[i]
            for j in range(c):
                if lvl >= h[j]:
                    continue
                ch = fixed.get((i, j))
                if ch is None:
                    ch = 'X' if rng.random() < 0.5 else 'O'
                    if makes_four(g, r, c, i, j, ch):
                        ch = 'O' if ch == 'X' else 'X'
                row[j] = ch
        return g

    PATS = ((1, 2, 2), (1, 2, 3), (2, 1, 2), (2, 1, 3), (3, 2, 2), (4, 1, 3))

    def pat_fill(r, c, h, fixed):
        A, B, D = rng.choice(PATS)
        sw = rng.randrange(2)
        mir = rng.randrange(2)
        g = [['.'] * c for _ in range(r)]
        for i in range(r):
            row = g[i]
            lvl = r - 1 - i
            for j in range(c):
                if lvl < h[j]:
                    jj = c - 1 - j if mir else j
                    row[j] = 'XO'[(((A * i + B * jj) // D) + sw) % 2]
        for (i, j), ch in fixed.items():
            g[i][j] = ch
        return g

    def rand_line(r, c):
        while True:
            di, dj = rng.choice(((0, 1), (1, 0), (1, 1), (1, -1)))
            i = rng.randrange(r)
            j = rng.randrange(c)
            cells = [(i + k * di, j + k * dj) for k in range(4)]
            if all(0 <= a < r and 0 <= b < c for a, b in cells):
                return cells

    def fmt(r, c, p, g):
        return '%d %d\n%s\n' % (r, c, p) + '\n'.join(''.join(row) for row in g)

    def make(kind, r, c, full=False):
        can_line = r >= 4 or c >= 4
        for _ in range(80):
            h = [r] * c if full else [rng.randint(0, r) for _ in range(c)]
            fixed = {}
            p = rng.choice('XO')
            w = None
            if kind != 'none' and can_line:
                cells = rand_line(r, c)
                if kind == 'won':
                    w = rng.choice('XO')
                    for (i, j) in cells:
                        fixed[(i, j)] = w
                        h[j] = max(h[j], r - i)
                else:
                    if cells[0][1] == cells[1][1]:
                        t = min(cells)
                    else:
                        t = rng.choice(cells)
                    for (i, j) in cells:
                        if (i, j) != t:
                            fixed[(i, j)] = p
                            h[j] = max(h[j], r - i)
                    h[t[1]] = r - 1 - t[0]
            g = pat_fill(r, c, h, fixed) if r * c > 3000 else fill(r, c, h, fixed)
            hx = has4(g, r, c, 'X')
            ho = has4(g, r, c, 'O')
            if hx and ho:
                continue
            if kind == 'won' and can_line:
                if not (hx or ho):
                    continue
            elif hx or ho:
                continue
            return fmt(r, c, p, g)
        return fmt(r, c, 'X', [['.'] * c for _ in range(r)])

    tests = [
        '1 1\nX\n.',
        '4 1\nX\n.\nX\nX\nX',
        '4 1\nO\n.\nX\nX\nX',
        '6 7\nX\n' + '\n'.join(['.......'] * 6),
        '4 4\nO\nXXXX\n....\n....\n....'.replace('XXXX\n....\n....\n....', '....\n....\n....\nXXXX'),
        '1 5\nX\nXXX.X',
        '3 3\nO\nXOX\nOXO\nXOX',
        '1 4\nX\nXXXX',
    ]
    for k in range(26):
        kind = ('none', 'won', 'can')[k % 3]
        r = rng.choice([4, 5, 6, 6, 7])
        c = rng.choice([4, 5, 7, 7, 8])
        tests.append(make(kind, r, c, full=(k % 7 == 6)))
    for k in range(6):
        kind = ('none', 'won', 'can')[k % 3]
        tests.append(make(kind, rng.randint(1, 3), rng.randint(5, 9)))
    for k in range(3):
        tests.append(make(('none', 'won', 'can')[k], rng.randint(12, 25), rng.randint(12, 25)))
    tests.append(make('none', 500, 500, full=True))
    tests.append(make('won', 500, 500))
    tests.append(make('can', 500, 500))
    tests.append(make('none', 400, 500))
    return tests

